"talkback/dialog_message_disable_exploration": {
"res": "angler:talkback:dialog_message_disable_exploration",
"en": "Are you sure you want to turn off Explore by touch?\n\nYour device will no longer respond to shortcut gestures or speak items when you touch the screen.",
"hu": "Biztosan kikapcsolja a Felfedezés érintéssel funkciót?\n\nEszköze a továbbiakban nem reagál a kézmozdulatokra és a hangvezérlés parancsaira, amikor megérinti a képernyőt.",
"de": "Möchtest du \"Tippen & Entdecken\" wirklich deaktivieren?\n\nDein Gerät reagiert dann nicht mehr auf Bewegungskürzel und benennt auch nicht die Elemente beim Berühren des Bildschirms.",
"fr": "Voulez-vous vraiment désactiver la fonctionnalité Explorer au toucher ?\n\nVotre appareil ne répondra plus aux gestes de raccourci et n'énoncera plus les éléments lorsque vous toucherez l'écran.",
"es": "¿Seguro que quieres desactivar la exploración táctil?\n\nTu dispositivo ya no responderá a los gestos de accesos directos ni a elementos hablados al tocar la pantalla."
},
"talkback/dialog_message_enable_tree_debug": {
"res": "angler:talkback:dialog_message_enable_tree_debug",
"en": "Are you sure you want to turn on node tree debugging?\n\nNode tree debugging exposes the content of your screen to your device's logs, which may be read by other applications.",
"hu": "Biztosan bekapcsolja a csomópont-hierarchia hibakeresést?\n\nA csomópont-hierarchia hibakeresés feltárja a képernyő tartalmát az eszköz naplóinak, amelyeket más alkalmazások is olvashatnak.",
"de": "Soll das Knotenstruktur-Debugging wirklich aktiviert werden?\n\nDadurch werden deine Bildschirminhalte in den Geräteprotokollen gespeichert, die möglicherweise von anderen Apps eingesehen werden.",
"fr": "Voulez-vous vraiment activer le débogage de l'arborescence de nœuds ?\n\nSi vous utilisez cette fonctionnalité, les journaux de votre appareil auront accès au contenu affiché sur votre écran, qui pourra être lu par d'autres applications.",
"es": "¿Seguro que quieres activar la depuración de árbol de nodos?\n\nEsta opción muestra el contenido de la pantalla en los registros del dispositivo y otras aplicaciones pueden consultarlo."
},
"talkback/dialog_title_disable_exploration": {
"res": "angler:talkback:dialog_title_disable_exploration",
"en": "Disable Explore by touch?",
"hu": "Letiltja a Felfedezés érintéssel funkciót?",
"de": "\"Tippen & Entdecken\" deaktivieren?",
"fr": "Désactiver la fonctionnalité Explorer au toucher ?",
"es": "¿Quieres inhabilitar la exploración táctil?"
},
"talkback/dialog_title_enable_tree_debug": {
"res": "angler:talkback:dialog_title_enable_tree_debug",
"en": "Enable Node Tree Debugging?",
"hu": "Engedélyezi a csomópont-hierarchia hibakeresést?",
"de": "Knotenstruktur-Debugging aktivieren?",
"fr": "Activer le débogage de l'arborescence des nœuds ?",
"es": "¿Habilitar la depuración de árbol de nodos?"
},
